  background: rgba(255, 255, 255, 0.38);
  padding: var(--space-1);
}
.sga-birth-source-header {
  text-align: center;
  margin-bottom: var(--space-0-85);
}
.sga-birth-source-header h3 {
  margin: 0;
  font-size: 1rem;
}
.sga-birth-source-header p {
  margin: var(--space-0-3) 0 0;
  font-size: 0.86rem;
  line-height: 1.45;
  color: rgba(20, 44, 47, 0.74);
}
.sga-birth-compare-note {
  border: var(--border-hairline) solid var(--lg-border);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.52);
  padding: var(--space-0-85) var(--space-1);
  margin-bottom: var(--space-0-9);
  text-align: center;
  line-height: 1.5;
}
.sga-birth-compare-note p {
  margin: 0;
}
.sga-birth-summary-box,
 .sga-birth-meta-box,
 .sga-birth-note-box {
  border: var(--border-hairline) solid var(--lg-border);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.52);
  padding: var(--space-0-95) var(--space-1);
}
.sga-birth-summary-box h3,
 .sga-birth-meta-box h3 {
  margin: 0 0 var(--space-0-7);
  text-align: center;
  font-size: 1rem;
}
.sga-birth-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(220px, 100%), 1fr));
  gap: var(--space-0-75);
  max-width: min(640px, 100%);
  margin: 0 auto;
  justify-content: center;
}
.sga-birth-summary-item {
  min-width: 0;
  border: 1.5px solid rgba(0, 131, 141, 0.24);
  border-radius: var(--radius);
  background: rgba(0, 131, 141, 0.07);
  padding: var(--space-0-95) var(--space-1);
  text-align: center;
  box-shadow: 0 0 0 1px rgba(0, 131, 141, 0.08) inset;
  color: #0b545c;
  overflow-wrap: anywhere;
}
.sga-birth-summary-item.is-ok {
  border-color: rgba(0, 131, 141, 0.36);
  background: rgba(0, 131, 141, 0.09);
  box-shadow: 0 0 0 1px rgba(0, 131, 141, 0.08) inset;
  color: #0b545c;
}
.sga-birth-summary-item.is-sga {
  border-color: rgba(198, 40, 40, 0.42);
  background: rgba(198, 40, 40, 0.10);
  box-shadow: 0 0 0 1px rgba(198, 40, 40, 0.12) inset;
  color: #9f1d1d;
}
.sga-birth-summary-item.is-missing {
  border-color: rgba(112, 124, 129, 0.32);
  background: rgba(112, 124, 129, 0.10);
  box-shadow: 0 0 0 1px rgba(112, 124, 129, 0.10) inset;
  color: rgba(20, 44, 47, 0.62);
}
.sga-birth-summary-label,
 .sga-birth-summary-value {
  display: block;
  font-size: 0.98rem;
  line-height: 1.45;
  font-weight: 600;
  color: inherit;
}
.sga-birth-summary-value {
  margin-top: var(--space-0-3);
}
.sga-birth-result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: var(--space-0-85);
  margin-top: var(--space-0-9);
}
.sga-birth-result-grid.is-single {
  grid-template-columns: minmax(0, 420px);
  justify-content: center;
}
.sga-birth-result-card {
  border: var(--border-hairline) solid var(--lg-border);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.58);
  padding: var(--space-0-95) var(--space-1);
}
.sga-birth-result-card h4 {
  margin: 0 0 var(--space-0-7);
  text-align: center;
  font-size: 0.98rem;
}
.sga-birth-result-card dl {
  margin: 0;
}
.sga-birth-result-card dl > div {
  display: flex;
  justify-content: space-between;
  gap: var(--space-0-9);
  padding: 0.34rem 0;
  border-top: var(--border-hairline) solid var(--line-teal-soft);
}
.sga-birth-result-card dl > div:first-child {
  border-top: 0;
  padding-top: 0;
}
.sga-birth-result-card dt,
 .sga-birth-result-card dd {
  margin: 0;
  line-height: 1.4;
}
.sga-birth-result-card dt {
  color: rgba(20, 44, 47, 0.78);
}
.sga-birth-result-card dd {
  text-align: right;
  font-weight: 600;
}
.sga-birth-note-box {
  margin-top: var(--space-0-9);
}
.sga-birth-note-box p,
 .sga-birth-meta-box p {
  margin: 0.18rem 0;
  line-height: 1.5;
}
.sga-birth-compare-reference-box,
 .sga-birth-compare-footnotes {
  margin-top: var(--space-1);
}
.sga-birth-compare-reference-box h3,
 .sga-birth-compare-footnotes h3 {
  margin: 0 0 var(--space-0-7);
  text-align: center;
  font-size: 1rem;
}
@media (max-width: 860px) {
 .sga-birth-summary-grid,
 .sga-birth-compare-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table {
    min-width: 0;
    border-collapse: separate;
    border-spacing: 0;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table thead {
    display: none;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table,
 .sga-birth-compare-table tbody,
 .sga-birth-compare-table tr,
 .sga-birth-compare-table th,
 .sga-birth-compare-table td {
    display: block;
    width: 100%;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table tbody tr {
    border: var(--border-hairline) solid var(--line-teal);
    border-radius: var(--radius-16);
    background: rgba(255, 255, 255, 0.62);
    margin-bottom: var(--space-0-8);
    padding: 0.15rem var(--space-0-9) var(--space-0-8);
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table tbody tr:last-child {
    margin-bottom: 0;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table tbody th[scope="row"] {
    border: 0;
    border-bottom: var(--border-hairline) solid rgba(0, 131, 141, 0.14);
    border-radius: 0;
    background: transparent;
    padding: 0.72rem 0 0.58rem;
    margin-bottom: 0.08rem;
    white-space: normal;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table tbody td {
    border: 0;
    border-top: var(--border-hairline) solid var(--line-teal-soft);
    background: transparent;
    padding: var(--space-0-5) 0;
    display: grid;
    grid-template-columns: minmax(110px, 48%) 1fr;
    gap: var(--space-0-7);
    align-items: start;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-table tbody td::before {
    content: attr(data-label);
    font-weight: 700;
    color: rgba(20, 44, 47, 0.74);
    line-height: 1.35;
  }
}
@media (max-width: 720px) {
.sga-birth-compare-badge {
    justify-self: start;
  }
}

